'use strict';

(function () {
  var UNAVAILABLE = { text: 'Status: unavailable', state: 'error' };
  var TIMEOUT_MS = 5000;

  // Pure: maps the outcome of the health call to what the page shows.
  // `result` is { ok, body } for a completed response, or null when the call failed.
  function describeHealth(result) {
    if (!result || !result.ok) return UNAVAILABLE;
    var body = result.body;
    if (!body || typeof body !== 'object' || typeof body.status !== 'string' || body.status === '') {
      return UNAVAILABLE;
    }
    return { text: 'Status: ' + body.status, state: 'ok' };
  }

  // Sends GET {baseUrl}/health once and returns { text, state }. Never throws.
  function checkHealth(fetchImpl, baseUrl) {
    var url = String(baseUrl || '').replace(/\/+$/, '') + '/health';
    var controller = typeof AbortController === 'function' ? new AbortController() : null;
    var timer = controller ? setTimeout(function () { controller.abort(); }, TIMEOUT_MS) : null;
    var options = { method: 'GET', headers: { Accept: 'application/json' } };
    if (controller) options.signal = controller.signal;

    return Promise.resolve()
      .then(function () { return fetchImpl(url, options); })
      .then(function (response) {
        if (!response.ok) return describeHealth({ ok: false });
        return response.json().then(
          function (body) { return describeHealth({ ok: true, body: body }); },
          function () { return describeHealth(null); }
        );
      })
      .catch(function () { return describeHealth(null); })
      .then(function (view) {
        if (timer) clearTimeout(timer);
        return view;
      });
  }

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { describeHealth: describeHealth, checkHealth: checkHealth };
  }

  if (typeof window !== 'undefined' && typeof document !== 'undefined') {
    var start = function () {
      var el = document.getElementById('status');
      var config = window.APP_CONFIG || {};
      checkHealth(window.fetch.bind(window), config.backendBaseUrl).then(function (view) {
        el.textContent = view.text;
        el.setAttribute('data-state', view.state);
      });
    };
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', start);
    } else {
      start();
    }
  }
})();
EOF
cat > test/app.test.js <<'EOF'
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { describeHealth, checkHealth } = require('../public/app.js');

function jsonResponse(status, body) {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: async () => body,
  };
}

test('describeHealth: ok response gives "Status: ok"', () => {
  assert.deepEqual(describeHealth({ ok: true, body: { status: 'ok' } }), { text: 'Status: ok', state: 'ok' });
});

test('describeHealth: failed call gives "Status: unavailable"', () => {
  assert.deepEqual(describeHealth(null), { text: 'Status: unavailable', state: 'error' });
});

test('describeHealth: non-2xx gives "Status: unavailable"', () => {
  assert.deepEqual(describeHealth({ ok: false }), { text: 'Status: unavailable', state: 'error' });
});

test('describeHealth: missing status field gives "Status: unavailable"', () => {
  assert.deepEqual(describeHealth({ ok: true, body: {} }), { text: 'Status: unavailable', state: 'error' });
});

test('checkHealth: sends one GET to {base}/health and renders ok', async () => {
  const calls = [];
  const fetchImpl = async (url, options) => {
    calls.push({ url, method: options.method });
    return jsonResponse(200, { status: 'ok' });
  };
  const view = await checkHealth(fetchImpl, 'http://127.0.0.1:8000/');
  assert.deepEqual(view, { text: 'Status: ok', state: 'ok' });
  assert.deepEqual(calls, [{ url: 'http://127.0.0.1:8000/health', method: 'GET' }]);
});

test('checkHealth: network error gives "Status: unavailable"', async () => {
  const view = await checkHealth(async () => { throw new TypeError('Failed to fetch'); }, 'http://x');
  assert.deepEqual(view, { text: 'Status: unavailable', state: 'error' });
});

test('checkHealth: non-2xx response gives "Status: unavailable"', async () => {
  const view = await checkHealth(async () => jsonResponse(503, { status: 'ok' }), 'http://x');
  assert.deepEqual(view, { text: 'Status: unavailable', state: 'error' });
});

test('checkHealth: invalid JSON gives "Status: unavailable"', async () => {
  const fetchImpl = async () => ({ ok: true, status: 200, json: async () => { throw new SyntaxError('bad'); } });
  const view = await checkHealth(fetchImpl, 'http://x');
  assert.deepEqual(view, { text: 'Status: unavailable', state: 'error' });
});
EOF
